function reviewsSection(){return `<section class="section review-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Customer reviews</div><h2 class="section-title">Trusted plumbing help across Southeast Michigan.</h2></div><div class="review-summary" aria-label="Google rating summary"><strong>4.7</strong><span>225 Google reviews</span><small>Verified review source connected on staging</small></div></div><div class="review-placeholder"><p>Current four- and five-star review cards will appear here using the staging-specific review widget. The incomplete HighLevel aggregate is intentionally suppressed.</p></div></div></section>`;}
function requestFormSection(){return `<section class="section section-alt"><div class="wrap contact-layout"><div class="contact-form-panel"><div class="eyebrow">Request plumbing service</div><h2>Tell the team what is happening.</h2><p>For an urgent or actively damaging condition, call ${business.phoneDisplay} instead of waiting for an online response.</p><form class="contact-form" aria-label="Homepage service request" onsubmit="return false"><div class="field-grid"><label>First Name <span aria-hidden="true">*</span><input type="text" autocomplete="given-name" required></label><label>Last Name <span aria-hidden="true">*</span><input type="text" autocomplete="family-name" required></label><label>Phone <span aria-hidden="true">*</span><input type="tel" autocomplete="tel" required></label><label>Email <span aria-hidden="true">*</span><input type="email" autocomplete="email" required></label></div><label>Message <span aria-hidden="true">*</span><textarea rows="5" required></textarea></label><label class="consent-field"><input type="checkbox"> I agree to receive service-related text messages. Message and data rates may apply.</label><button class="btn btn-primary" type="submit">Submit</button><p class="form-note">Review only—this form does not send information.</p></form></div><aside class="contact-sidebar"><div class="sidebar-card"><div class="eyebrow">Call any time</div><h2>${business.phoneDisplay}</h2><p>24/7 emergency plumbing help for homes and businesses across Macomb, Oakland, and Wayne counties.</p><a class="btn btn-primary" href="${business.phoneHref}">Call now</a></div></aside></div></section>`;}

function serviceCards(limit){const rows=typeof limit==='number'?serviceInventory.slice(0,limit):serviceInventory;return rows.map(([slug,name,description,image])=>`<article class="card" id="service-${slug}"><div class="card-media"><img src="assets/images/${image}" alt="${esc(name)}"></div><div class="card-body"><h3>${esc(name)}</h3><p>${esc(description)}</p><a class="text-link" href="${servicePageUrl(slug)}">Explore service</a></div></article>`).join('');}

function homePage(){return `${header()}<main id="main"><section class="hero" style="--hero:url('images/tech-andrew-vans-v16.jpg');--hero-position:center 45%"><div class="wrap"><div class="hero-content"><div class="eyebrow">Chesterfield plumbing team • serving three counties</div><h1>Plumbing help when your home or business can’t wait.</h1><p>Emergency, drain, sewer, water-heater, excavation, and full-service plumbing across Macomb, Oakland, and Wayne counties.</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="${pageUrl('contact')}">Request service</a></div><div class="hero-proof"><span>24/7 emergency</span><span>Residential</span><span>Commercial</span></div></div></div></section>${trustBar()}<section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Plumbing service without the runaround</div><h2 class="section-title">Start with the problem. Leave with a clear plan.</h2></div><p class="lead">Whether a fixture is leaking, a drain keeps backing up, or a buried line needs attention, the first step is understanding what failed and what the property actually needs.</p></div><div class="cards">${serviceCards(6)}</div><p style="text-align:center;margin-top:30px"><a class="btn btn-outline" href="${pageUrl('services')}">See every plumbing service</a></p></div></section><section class="section section-alt"><div class="wrap split"><div class="split-media"><img src="assets/images/team-full-plus-two-polos-v5.jpg" alt="Frost and Kretsch Plumbing team"></div><div class="split-copy"><div class="eyebrow">Local team, useful communication</div><h2>Plumbing help when you need it.</h2><p>Frost &amp; Kretsch Plumbing supports homeowners, businesses, facilities, and managed properties from Chesterfield. Some calls begin with an obvious problem—a leaking faucet, a clogged drain, or no hot water. Others require a wider look because several fixtures are affected, the same backup keeps returning, or moisture is appearing without a visible source.</p><p>The team starts with the symptoms, the property, and the systems involved. On-site findings then guide the practical next step: repair, replacement, cleaning, camera inspection, testing, or excavation. That approach helps separate the immediate problem from related conditions that may also need attention.</p><ul class="checklist"><li>Residential and commercial plumbing service</li><li>Drain, sewer, camera, and excavation capability</li><li>Tank and tankless water-heater support</li><li>24/7 availability for urgent plumbing conditions</li></ul><a class="text-link" href="${pageUrl('about')}">Learn about Frost &amp; Kretsch</a></div></div></section><section class="section section-dark"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Complete service coverage</div><h2 class="section-title">One team. Eleven clear service paths.</h2></div><p class="lead">Choose the service closest to the problem, or call with the symptoms if you are not sure where to begin.</p></div><div class="service-grid">${serviceInventory.map(([slug,name,description],index)=>`<a class="service-link" href="${servicePageUrl(slug)}"><span class="service-icon">${String(index+1).padStart(2,'0')}</span><span><b>${esc(name)}</b><span>${esc(description)}</span></span></a>`).join('')}</div></div></section><section class="section"><div class="wrap location-panel"><div class="location-copy"><div class="eyebrow">Macomb • Oakland • Wayne</div><h2>Plumbing coverage across three counties.</h2><p>Frost &amp; Kretsch Plumbing is based at ${business.address} and serves communities across Macomb, Oakland, and Wayne counties. Call with the service address and a description of the problem so the team can confirm coverage and the right service path.</p><p>Customers throughout the area use the same main number for residential, commercial, drain, sewer, water-heater, and emergency plumbing help.</p><div class="hero-actions"><a class="btn btn-primary" href="${pageUrl('service-areas')}">Explore service area</a><a class="btn btn-secondary" href="${business.phoneHref}">Call now</a></div></div><div class="map-card"><div><strong>Primary Chesterfield location</strong><br>${business.address}<br><small>Interactive map connected during staging</small></div></div></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><div class="eyebrow">A simple service process</div><h2 class="section-title">From first call to next step.</h2></div><p class="lead">Clear details at the beginning help the team understand the urgency, likely specialty, and information needed for the visit.</p></div><div class="process"><div class="step"><h3>Tell us what you see</h3><p>Share the address, symptoms, timing, affected fixtures, and whether water or sewage is actively spreading.</p></div><div class="step"><h3>Confirm the service path</h3><p>The team identifies the likely plumbing specialty and any immediate property-protection steps that can be discussed safely.</p></div><div class="step"><h3>Diagnose the condition</h3><p>On-site findings guide repair, replacement, cleaning, inspection, testing, or excavation recommendations.</p></div><div class="step"><h3>Review the next step</h3><p>Understand what was found, what is being recommended, and how the proposed work addresses the confirmed problem.</p></div></div></div></section>${faq([['Do you provide 24/7 emergency plumbing service?','Yes. Call the main number any time for urgent plumbing help with active leaks, sewage backups, burst piping, failed sump systems, and other conditions that may increase property damage.'],['Where is Frost & Kretsch Plumbing located?','The primary location is 47212 Jefferson Ave, Chesterfield, MI 48047.'],['Do you serve both homes and businesses?','Yes. Frost & Kretsch Plumbing provides residential and commercial plumbing support for homeowners, businesses, facilities, and managed properties.'],['What areas do you serve?','Frost & Kretsch Plumbing serves Macomb, Oakland, and Wayne counties. Call with the property address to confirm coverage.']])}${reviewsSection()}${requestFormSection()}${cta('Ready for a clearer plumbing answer?')}</main>${footer()}`;}

function servicesPage(){return `${header()}<main id="main"><section class="hero" style="--hero:url('images/dsc09358.webp')"><div class="wrap"><div class="hero-content"><div class="eyebrow">Residential • commercial • emergency</div><h1>Focused plumbing services for the problem in front of you.</h1><p>Choose the service that best matches the symptoms. If you are unsure, call and describe what is happening.</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="${pageUrl('contact')}">Request service</a></div></div></div></section>${trustBar()}<section class="section"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">Find the right service</div><h2>Plumbing problems do not always stay inside one category.</h2><p>A slow drain may be limited to one fixture, or it may be the first sign of a larger branch or sewer-line problem. Water near a mechanical room may come from a supply pipe, water heater, drain connection, sump system, or another nearby source. The service call begins with what is happening, where it appears, when it started, and how many fixtures or areas are affected.</p><p>Frost &amp; Kretsch Plumbing provides residential, commercial, drain, sewer, equipment, gas-line, water-treatment, and excavation services from Chesterfield across Macomb, Oakland, and Wayne counties. Use the service descriptions below to find the closest match. If several systems are involved—or the source is unclear—call and describe the complete symptom.</p><h2>When the problem is urgent</h2><p>Call immediately for active water release, sewage backing into the property, burst piping, loss of essential plumbing, a failed sump system during wet conditions, or another situation that may worsen while you wait. Avoid electrical hazards, gas components, contaminated water, and repairs you cannot perform safely.</p></article><aside class="sidebar"><div class="sidebar-card"><h3>Helpful details to share</h3><p>Property address and type</p><p>Every affected fixture or area</p><p>When the problem started</p><p>Whether water or sewage is spreading</p><p>Previous repairs or recurring symptoms</p></div><div class="sidebar-card"><h3>Not sure where to start?</h3><p>Call the main number and describe the complete problem.</p><a class="btn btn-primary btn-small" href="${business.phoneHref}">${business.phoneDisplay}</a></div></aside></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Complete plumbing service</div><h2 class="section-title">Choose the service that matches the problem.</h2></div><p class="lead">Each service page explains common warning signs, service scope, related systems, planning details, and frequently asked questions.</p></div><div class="cards">${serviceCards()}</div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">What to expect</div><h2 class="section-title">A practical path from symptoms to a repair plan.</h2></div><p class="lead">The final recommendation depends on the property, access, system condition, and what the inspection confirms.</p></div><div class="process"><div class="step"><h3>Describe the condition</h3><p>Explain what you see, hear, smell, or feel and whether the problem is changing.</p></div><div class="step"><h3>Identify the system</h3><p>The affected fixtures, piping, equipment, drains, or buried lines shape the diagnostic path.</p></div><div class="step"><h3>Confirm the cause</h3><p>Inspection and testing narrow the problem before larger work is recommended.</p></div><div class="step"><h3>Review the scope</h3><p>Repair, replacement, cleaning, inspection, or excavation follows the confirmed need.</p></div></div></div></section>${reviewsSection()}${cta()}</main>${footer()}`;}

function waterHeaterPage(){return `${header()}<main id="main"><section class="hero" style="--hero:url('images/water-heater-uniform-v5.png');--hero-position:center 45%"><div class="wrap"><div class="hero-content"><div class="eyebrow">Tank and tankless water heaters</div><h1>Restore dependable hot water with a system-level plan.</h1><p>Diagnosis, repair, replacement, and installation planning for homes and businesses across Macomb, Oakland, and Wayne counties.</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="${pageUrl('contact')}">Request service</a></div></div></div></section>${trustBar()}<section class="section"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">When to call</div><h2>Hot-water symptoms deserve more than a quick guess.</h2><p>No hot water, slow recovery, leaking around the tank, unusual sounds, temperature swings, and changes in water color or odor can point to different causes. The right next step depends on the equipment, fuel or power source, venting, drainage, age, demand, and confirmed condition.</p><p>Frost &amp; Kretsch Plumbing evaluates the complete setup before recommending repair or replacement. Tank and tankless options are considered around the property—not treated as interchangeable products.</p><div class="callout"><strong>Call now when:</strong> water is actively spreading, the unit shows unsafe operation, or waiting may increase property damage.</div><h2>Signs it is time to schedule service</h2><ul><li>No hot water or inconsistent temperature</li><li>Visible leaking or moisture near the unit</li><li>Unusual popping, rumbling, or cycling</li><li>Hot water runs out much sooner than normal</li><li>Rust-colored water or recurring odor</li><li>An aging system needs replacement planning</li></ul></article><aside class="sidebar"><div class="sidebar-card"><h3>Related plumbing help</h3><a href="${pageUrl('services')}">Leak detection &amp; pipe repair →</a><a href="${pageUrl('services')}">Fixture plumbing →</a><a href="${pageUrl('services')}">Commercial plumbing →</a><a href="${pageUrl('service-areas')}">Service Area →</a></div><div class="sidebar-card"><h3>Emergency?</h3><p>Call any time for urgent plumbing help.</p><a class="btn btn-primary btn-small" href="${business.phoneHref}">${business.phoneDisplay}</a></div></aside></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Service scope</div><h2 class="section-title">What we can help with.</h2></div><p class="lead">The scope is confirmed after the team understands the property, symptoms, access, and equipment condition.</p></div><div class="cards offering-grid"><article class="card"><div class="card-body"><div class="service-icon">01</div><h3>Diagnosis and repair</h3><p>Evaluate heating, controls, water connections, drainage, venting, and visible failure conditions.</p></div></article><article class="card"><div class="card-body"><div class="service-icon">02</div><h3>Tank replacement</h3><p>Plan capacity, fuel or power, connections, safe venting, drainage, and service access.</p></div></article><article class="card"><div class="card-body"><div class="service-icon">03</div><h3>Tankless systems</h3><p>Review demand, gas or electrical capacity, venting, water quality, and maintenance needs.</p></div></article><article class="card"><div class="card-body"><div class="service-icon">04</div><h3>Commercial hot water</h3><p>Coordinate the system around building use, recovery demand, access, and operational impact.</p></div></article></div></div></section><section class="section"><div class="wrap split"><div class="split-media"><img src="assets/images/team-full-v4.jpg" alt="Frost and Kretsch Plumbing team"></div><div class="split-copy"><div class="eyebrow">Planning the visit</div><h2>Details that help prepare the right service path.</h2><p>Before calling, record the fuel type, approximate tank size, visible model information, where water is appearing, and whether the problem affects all hot-water fixtures.</p><p>For replacement planning, household or business demand, existing venting or electrical capacity, available space, drainage, shutoffs, and routine maintenance expectations all matter.</p><ul class="checklist"><li>Share the property address and active symptom</li><li>Note equipment type, age, and visible model details</li><li>Describe when the condition started or changed</li><li>Do not remove covers or work around gas or electrical components</li></ul></div></div></section>${faq([['Do you repair both tank and tankless water heaters?','Yes. The service path covers diagnosis, repair, replacement, and installation planning for both system types.'],['How do I know whether to repair or replace the unit?','The decision depends on the confirmed failure, age, condition, safety, efficiency, repair scope, and whether the system still fits the property’s hot-water demand.'],['Can you help choose the right size?','Yes. Capacity should be based on actual demand, recovery needs, available utilities, space, venting, and the way the property uses hot water.'],['What should I do if the water heater is leaking?','If water is actively spreading and you can safely identify the correct shutoff, limiting the water source may reduce damage. Avoid gas or electrical components and call for help.']])}${reviewsSection()}${cta('Need help with a water heater?')}</main>${footer()}`;}

function serviceAreasPage(){return `${header()}<main id="main"><section class="hero" style="--hero:url('images/dsc09538.webp');--hero-position:center 55%"><div class="wrap"><div class="hero-content"><div class="eyebrow">Macomb • Oakland • Wayne</div><h1>Plumbing service across three Southeast Michigan counties.</h1><p>Choose a community page for local coverage and direct service links, or call with the property address and plumbing problem.</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="${pageUrl('chesterfield')}">View Chesterfield page</a></div></div></div></section><section class="section"><div class="wrap location-panel"><div class="location-copy"><div class="eyebrow">Primary location</div><h2>Frost &amp; Kretsch Plumbing in Chesterfield</h2><p>${business.address}</p><p>The Chesterfield team supports plumbing calls throughout the listed service territory. Customers use the same main number for residential, commercial, drain, sewer, water-heater, sump-pump, pipe, gas-line, water-treatment, fixture, excavation, and emergency plumbing needs.</p><p>Call with the property address and a description of the condition so coverage and the appropriate service path can be confirmed.</p><a class="btn btn-primary" href="${pageUrl('chesterfield')}">Chesterfield service page</a></div><div class="map-card"><div><strong>Chesterfield map</strong><br>${business.address}<br><small>Interactive map connected during staging</small></div></div></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Southeast Michigan coverage</div><h2 class="section-title">Communities served across three counties.</h2></div><p class="lead">These local pages help customers confirm service coverage and connect directly to the plumbing service that fits the problem.</p></div><div class="county-grid">${Object.entries(priorityCities).map(([county,cities])=>`<article class="county-card"><h3>${esc(county)}</h3><p>${cities.map(city=>city==='Chesterfield'?`<a href="${pageUrl('chesterfield')}">${esc(city)}</a>`:esc(city)).join(' • ')}</p></article>`).join('')}</div></div></section><section class="section"><div class="wrap split"><div class="split-media"><img src="assets/images/team-office-staff-wide-v5.jpg" alt="Frost and Kretsch Plumbing team and service vehicles"></div><div class="split-copy"><div class="eyebrow">Local plumbing help</div><h2>The property and the symptoms shape the service call.</h2><p>Homes, businesses, facilities, and managed properties can have very different access, piping, drainage, equipment, and operating needs. Finished basements, aging supply lines, high-use restrooms, recurring sewer symptoms, storm conditions, and underground piping may all affect the diagnostic path.</p><p>When calling, share the service address, property type, affected fixtures or systems, when the issue began, and whether the condition is active. If several fixtures are involved, mention all of them. Shared symptoms can point toward a branch drain, main sewer, pressure condition, water source, or equipment problem.</p><ul class="checklist"><li>Residential and commercial plumbing coverage</li><li>24/7 availability for urgent plumbing conditions</li><li>Drain, sewer, camera, and excavation service</li><li>One verified Chesterfield business and main phone number</li></ul></div></div></section>${faq([['What counties does Frost & Kretsch Plumbing serve?','The service area includes Macomb, Oakland, and Wayne counties. Call with the exact property address to confirm coverage.'],['Is every city page a separate plumbing office?','No. Frost & Kretsch Plumbing is based in Chesterfield. Community pages describe service coverage and connect customers to the same verified company.'],['Do you serve both homes and commercial properties?','Yes. Residential and commercial plumbing service is available throughout the listed territory.'],['Who should I call for an urgent problem?','Call the main number at any time for active leaks, sewage backups, burst piping, failed sump systems, or other urgent plumbing conditions.']])}${reviewsSection()}${cta()}</main>${footer()}`;}

function chesterfieldPage(){return `${header()}<main id="main"><section class="hero" style="--hero:url('images/fleet-of-vans-shop-v5.jpg');--hero-position:center 42%"><div class="wrap"><div class="hero-content"><div class="eyebrow">Plumbing service in Chesterfield</div><h1>A Chesterfield plumbing team you can call around the clock.</h1><p>Residential, commercial, drain, sewer, water-heater, sump-pump, excavation, gas-line, and 24/7 emergency plumbing support.</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="${pageUrl('contact')}">Request service</a></div></div></div></section>${trustBar()}<section class="section"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">Chesterfield homes and businesses</div><h2>Local plumbing service connected to the right specialist page.</h2><p>Frost &amp; Kretsch Plumbing is based at ${business.address}. This page gives Chesterfield customers one useful local route while keeping detailed guidance on the appropriate plumbing-service pages.</p><p>Homes, businesses, finished basements, aging piping, high-use fixtures, storm conditions, and underground infrastructure can shape the service call. Explain what is happening, when it started, and whether water or sewage is actively affecting the property.</p><h2>Common reasons Chesterfield customers call</h2><ul><li>Leaking fixtures, valves, supply lines, and exposed piping</li><li>Slow drains, recurring clogs, and main-line backups</li><li>Water-heater performance, leaks, and replacement planning</li><li>Sump-pump, discharge, and backup-system concerns</li><li>Commercial restroom, drain, and plumbing needs</li><li>Gas lines, underground lines, and excavation work</li></ul><div class="callout"><strong>Urgent condition?</strong> Call ${business.phoneDisplay} any time for active leaks, sewage backups, burst piping, or other plumbing emergencies.</div></article><aside class="sidebar"><div class="sidebar-card"><h3>Popular services</h3>${serviceInventory.slice(0,7).map(([slug,name])=>`<a href="${servicePageUrl(slug)}">${esc(name)} →</a>`).join('')}</div><div class="sidebar-card"><h3>Primary location</h3><p>${business.address}</p><a href="${business.phoneHref}">${business.phoneDisplay}</a></div></aside></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Service connections</div><h2 class="section-title">Chesterfield plumbing services.</h2></div><p class="lead">Choose a focused service page for deeper warning signs, process information, and FAQs.</p></div><div class="service-grid">${serviceInventory.map(([slug,name,description],index)=>`<a class="service-link" href="${servicePageUrl(slug)}"><span class="service-icon">${String(index+1).padStart(2,'0')}</span><span><b>${esc(name)}</b><span>${esc(description)}</span></span></a>`).join('')}</div></div></section>${faq([['Where is Frost & Kretsch Plumbing located?','The headquarters is at 47212 Jefferson Ave, Chesterfield, MI 48047.'],['Do you provide 24/7 emergency service in Chesterfield?','Yes. Call the main number at any hour for urgent plumbing help.'],['Do you work with Chesterfield businesses and managed properties?','Yes. The commercial service path supports businesses, facilities, and property professionals.'],['Can you help with sewer and underground line problems?','Yes. Drain cleaning, camera inspection, sewer-line repair planning, and excavation are included in the service architecture.']])}${cta('Call a Chesterfield plumbing team')}</main>${footer()}`;}

function aboutPage(){return `${header()}<main id="main"><section class="hero" style="--hero:url('images/team-office-staff-wide-v5.jpg');--hero-position:center 48%"><div class="wrap"><div class="hero-content"><div class="eyebrow">Frost &amp; Kretsch Plumbing</div><h1>Local crews. Straight answers. Plumbing done carefully.</h1><p>Meet the Chesterfield plumbing company serving homes and businesses across Macomb, Oakland, and Wayne counties.</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="${pageUrl('contact')}">Contact the team</a></div></div></div></section><section class="section"><div class="wrap split"><div class="split-media"><img src="assets/images/team-full-v4.jpg" alt="Frost and Kretsch Plumbing team in front of service vehicles"></div><div class="split-copy"><div class="eyebrow">Built for local service</div><h2>One plumbing team for the fixture, the equipment, and the buried line.</h2><p>Frost &amp; Kretsch Plumbing supports residential and commercial customers from Chesterfield across Macomb, Oakland, and Wayne counties. The work ranges from leaking fixtures, failed valves, damaged piping, and hot-water problems to recurring drain backups, sewer inspection, underground line repair, excavation, gas piping, water treatment, and the plumbing systems businesses depend on every day.</p><p>That range matters because the visible symptom does not always identify the source. A wet basement may involve a supply leak, drainage issue, water heater, or sump system. A repeated clog may require more than another basic clearing. Several affected fixtures may point toward a branch drain or main sewer rather than separate fixture problems.</p><p>The team begins with the complete condition, then matches the inspection and repair plan to the property and system involved.</p></div></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Full-service plumbing</div><h2 class="section-title">Support for homes, businesses, and larger underground work.</h2></div><p class="lead">Customers have one company to call for routine repairs, specialized equipment, commercial coordination, and urgent plumbing conditions.</p></div><div class="cards offering-grid"><article class="card"><div class="card-body"><h3>Residential plumbing</h3><p>Fixtures, toilets, faucets, disposals, exposed piping, valves, leaks, water heaters, sump pumps, drains, and the connected systems serving the home.</p></div></article><article class="card"><div class="card-body"><h3>Commercial plumbing</h3><p>Repairs, fixtures, drains, shutoffs, gas piping, water treatment, tenant work, planned improvements, and communication around occupied properties.</p></div></article><article class="card"><div class="card-body"><h3>Drain, sewer, and excavation</h3><p>Drain cleaning, camera inspection, line evaluation, repair planning, and access to underground water or sewer piping when excavation is required.</p></div></article><article class="card"><div class="card-body"><h3>24/7 emergency help</h3><p>A direct call route for active leaks, burst piping, sewage backups, failed sump systems, and other urgent conditions that may increase property damage.</p></div></article></div></div></section><section class="section section-dark"><div class="wrap"><div class="section-head"><div><div class="eyebrow">How service begins</div><h2 class="section-title">Start with what is happening, then build the right plan.</h2></div><p class="lead">Good plumbing work begins before parts are replaced or walls are opened.</p></div><div class="process"><div class="step"><h3>Listen first</h3><p>The visible symptom, timing, affected fixtures, and property type shape the first diagnostic path.</p></div><div class="step"><h3>Inspect the system</h3><p>Accessible testing and on-site findings help narrow the cause before larger work is recommended.</p></div><div class="step"><h3>Explain the options</h3><p>The proposed work should connect directly to what was found and identify practical next steps.</p></div><div class="step"><h3>Complete the right scope</h3><p>Repair, replacement, cleaning, testing, inspection, or excavation follows the confirmed need.</p></div></div></div></section><section class="section"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">Planning around the property</div><h2>Residential and commercial calls require different coordination.</h2><p>For homeowners, clear explanations help separate the immediate plumbing repair from any drying, finish, or restoration work that may follow. For businesses, facilities, and managed properties, the plan may also need to account for operating hours, occupied areas, shutoffs, tenants, customers, locked spaces, and the people who need updates.</p><p>When you call, share the service address, property type, active symptom, when it started, and every fixture or area affected. Photos, equipment information, and previous repair findings can also help prepare the visit.</p></article><aside class="sidebar"><div class="sidebar-card"><h3>Company resources</h3><p>Local Chesterfield team</p><p>Branded service vehicles</p><p>Drain and sewer equipment</p><p>Excavation capability</p><p>Residential and commercial experience</p></div><div class="sidebar-card"><h3>Need plumbing help?</h3><a class="btn btn-primary btn-small" href="${business.phoneHref}">${business.phoneDisplay}</a></div></aside></div></section>${faq([['Where is Frost & Kretsch Plumbing located?','The primary business location is 47212 Jefferson Ave, Chesterfield, MI 48047.'],['Does the company serve homes and businesses?','Yes. Frost & Kretsch Plumbing provides residential and commercial plumbing service across Macomb, Oakland, and Wayne counties.'],['Is emergency plumbing available after normal hours?','Yes. Call the main number at any time for urgent plumbing help.'],['What information should I provide when I call?','Share the service address, property type, active symptom, when it started, every affected fixture or area, and whether water or sewage is spreading.']])}${reviewsSection()}${cta()}</main>${footer()}`;}

function contactPage(){return `${header()}<main id="main"><section class="hero" style="--hero:url('images/team-office-staff-wide-v5.jpg');--hero-position:center 58%"><div class="wrap"><div class="hero-content"><div class="eyebrow">Call or request service</div><h1>Tell us what is happening.</h1><p>For urgent plumbing help, call now. For planned service, share the property location, symptoms, and the best way to reach you.</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="#service-request">Use the contact form</a></div></div></div></section><section class="section" id="service-request"><div class="wrap contact-layout"><div class="contact-form-panel"><div class="eyebrow">Request plumbing service</div><h2>Complete the form and the team will follow up.</h2><p>Urgent or actively damaging condition? Call ${business.phoneDisplay} instead of waiting for an online response.</p><form class="contact-form" aria-label="Request plumbing service" onsubmit="return false"><div class="field-grid"><label>First Name <span aria-hidden="true">*</span><input type="text" autocomplete="given-name" required></label><label>Last Name <span aria-hidden="true">*</span><input type="text" autocomplete="family-name" required></label><label>Phone <span aria-hidden="true">*</span><input type="tel" autocomplete="tel" required></label><label>Email <span aria-hidden="true">*</span><input type="email" autocomplete="email" required></label></div><label>Message <span aria-hidden="true">*</span><textarea rows="6" required></textarea></label><label class="consent-field"><input type="checkbox"> I agree to receive service-related text messages. Message and data rates may apply.</label><button class="btn btn-primary" type="submit">Submit</button><p class="form-note">Review only—this form does not send information.</p></form></div><aside class="contact-sidebar"><div class="sidebar-card"><div class="eyebrow">Contact details</div><h2>Frost &amp; Kretsch Plumbing</h2><p><strong>Address</strong><br>${business.address}</p><p><strong>Phone</strong><br><a href="${business.phoneHref}">${business.phoneDisplay}</a></p><p><strong>Email</strong><br><a href="mailto:${business.email}">${business.email}</a></p><p>Emergency plumbing availability is promoted 24 hours a day, seven days a week.</p></div><div class="map-card"><div><strong>Chesterfield map</strong><br>${business.address}<br><small>Interactive map connected during staging</small></div></div></aside></div></section><section class="section section-alt"><div class="wrap split"><div class="split-media"><img src="assets/images/team-crew-van-close-v16.jpg" alt="Frost and Kretsch Plumbing crew and service van"></div><div class="split-copy"><div class="eyebrow">Helpful details</div><h2>What to include with a service request.</h2><p>Share the property address, when the problem started, what fixtures or systems are affected, and whether water or sewage is actively spreading.</p><ul class="checklist"><li>Property type and service address</li><li>Symptoms, timing, and visible damage</li><li>Equipment details when known</li><li>Best phone number and contact time</li></ul></div></div></section>${reviewsSection()}${cta('Urgent plumbing problem? Call now.')}</main>${footer()}`;}

function architecturePage(){const services=serviceInventory.map(([,name,,,url])=>`<li><span class="url-list">${url}</span> — ${esc(name)}</li>`).join('');const cities=Object.values(priorityCities).flat().map(city=>`<li><span class="url-list">/service-area/${city.toLowerCase().replace(/\./g,'').replace(/\s+/g,'-')}/</span> — ${esc(city)}</li>`).join('');return `${header()}<main id="main"><section class="simple-hero"><div class="wrap"><div class="eyebrow">Proposed lean architecture</div><h1>One page for each search intent.</h1><p>This review sitemap replaces service-by-city multiplication with final service hubs, a controlled priority-city set, and one blog stream.</p></div></section><section class="section"><div class="wrap"><div class="template-note"><strong>Architecture status:</strong> Core pages and service URLs are proposed as final. The nine-city launch set is supported by current FK Search Console and consolidation needs, but final redirect targets still require the other three domains’ inventories.</div><div class="architecture-grid"><article class="architecture-card"><h2>Core pages</h2><ul><li><span class="url-list">/</span> — Home</li><li><span class="url-list">/about/</span> — About</li><li><span class="url-list">/contact-us/</span> — Contact (preserved existing URL)</li><li><span class="url-list">/reviews/</span> — Reviews</li><li><span class="url-list">/service-area/</span> — Service Area</li><li><span class="url-list">/financing-coupons/</span> — Financing &amp; Coupons</li><li><span class="url-list">/faq/</span> — FAQ</li><li><span class="url-list">/blog/</span> — One blog stream</li><li><span class="url-list">/privacy/</span> — Privacy</li><li><span class="url-list">/terms/</span> — Terms &amp; Conditions</li><li><span class="url-list">/services/</span> — Services overview</li><li><span class="url-list">/services/residential-plumbing/</span> — Residential navigation hub</li></ul></article><article class="architecture-card"><h2>Core services</h2><ul>${services}</ul></article><article class="architecture-card"><h2>Initial priority cities</h2><ul>${cities}</ul></article><article class="architecture-card"><h2>Consolidation rules</h2><ul><li>No separate service × city pages</li><li>Plumbing-only company content and navigation</li><li>No invented office addresses</li><li>Old URLs receive one-hop page-to-page redirects</li><li>One stable lowercase, hyphenated URL per intent</li><li>Exact Chesterfield NAP in footer and business schema</li><li>GBP strategy and the second Chesterfield location remain future phases</li></ul></article></div></div></section>${cta()}</main>${footer()}`;}

function audiencePage({type,hero,eyebrow,title,lead,support,heading,intro,checklist,slugs,planningHeading,planningCopy,planningList,faqItems}){
  const selected=serviceInventory.filter(([slug])=>slugs.includes(slug));
  return `${header()}<main id="main"><section class="hero" style="--hero:url('images/${hero}');--hero-position:center 48%"><div class="wrap"><div class="hero-content"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${lead}</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="${pageUrl('contact')}">Request service</a></div><div class="hero-proof"><span>24/7 emergency</span><span>${type}</span><span>Three-county coverage</span></div></div></div></section>${trustBar()}<section class="section"><div class="wrap split"><div class="split-media"><img src="assets/images/${support}" alt="Frost and Kretsch Plumbing team and fleet"></div><div class="split-copy"><div class="eyebrow">Focused plumbing support</div><h2>${heading}</h2>${intro.map(paragraph=>`<p>${paragraph}</p>`).join('')}<ul class="checklist">${checklist.map(item=>`<li>${item}</li>`).join('')}</ul></div></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><div class="eyebrow">${type} services</div><h2 class="section-title">Choose the service that matches the problem.</h2></div><p class="lead">If you are unsure which path fits, call and describe the symptoms, timing, affected systems, and property.</p></div><div class="cards">${selected.map(([slug,name,description,image])=>`<article class="card"><div class="card-media"><img src="assets/images/${image}" alt="${esc(name)}"></div><div class="card-body"><h3>${esc(name)}</h3><p>${esc(description)}</p><a class="text-link" href="${servicePageUrl(slug)}">Explore service</a></div></article>`).join('')}</div></div></section><section class="section"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">Preparing for service</div><h2>${planningHeading}</h2>${planningCopy.map(paragraph=>`<p>${paragraph}</p>`).join('')}<ul>${planningList.map(item=>`<li>${item}</li>`).join('')}</ul><div class="callout"><strong>Urgent condition?</strong> Call ${business.phoneDisplay} any time for active leaks, sewage backups, burst piping, failed sump systems, or other plumbing problems that may worsen while you wait.</div></article><aside class="sidebar"><div class="sidebar-card"><h3>Service area</h3><p>Frost &amp; Kretsch Plumbing serves Macomb, Oakland, and Wayne counties from Chesterfield.</p><a href="${pageUrl('service-areas')}">Explore Service Areas →</a></div><div class="sidebar-card"><h3>Need help choosing?</h3><p>Describe the complete symptom and every fixture or area affected.</p><a class="btn btn-primary btn-small" href="${business.phoneHref}">${business.phoneDisplay}</a></div></aside></div></section>${faq(faqItems)}${reviewsSection()}${cta()}</main>${footer()}`;
}

function residentialPage(){return audiencePage({type:'Residential',hero:'residential-uniform-v3.png',eyebrow:'Residential plumbing services',title:'Clear plumbing help for the systems your home depends on.',lead:'Emergency, drain, sewer, water-heater, sump-pump, pipe, gas-line, water-treatment, and fixture plumbing across Macomb, Oakland, and Wayne counties.',support:'dsc09358.webp',heading:'Start with the symptoms and the systems affected.',intro:['A plumbing problem may begin at one fixture, but the source can involve a supply line, drain branch, water heater, sump system, main sewer, or buried pipe. Frost & Kretsch Plumbing works across the connected systems serving the home so the recommendation can address the confirmed condition rather than only the most visible symptom.','Tell the team where the problem appears, when it started, whether it has happened before, and whether more than one fixture or area is affected. Those details help distinguish an isolated repair from a larger drainage, pressure, equipment, or piping concern.'],checklist:['Leaking faucets, toilets, valves, and exposed piping','Slow drains, recurring clogs, and sewer backups','Water-heater and sump-pump problems','Kitchen, bathroom, gas-line, and water-treatment needs'],slugs:['emergency','drain-cleaning','sewer-camera','sewer-line','water-heater','sump-pump','leak-pipe','gas-line','water-treatment','fixtures'],planningHeading:'Details that help prepare the residential service visit.',planningCopy:['Share the property address, every fixture or room affected, when the condition began, and whether water or sewage is actively spreading. Mention recent remodeling, previous repairs, recurring symptoms, unusual sounds or odors, and any equipment model information you can identify safely.','If the problem involves a finished area, electrical equipment, gas piping, contaminated water, or a rapidly changing condition, avoid unsafe access and explain the risk when you call. The team can then identify the appropriate first step and specialty.'],planningList:['Property address and best on-site contact','Every affected fixture, room, or system','Visible moisture, backup, noise, odor, or loss of service','Photos or model information when safely available'],faqItems:[['Do you provide 24/7 residential plumbing service?','Yes. Call the main number at any time for urgent plumbing help.'],['Can you help when several drains or fixtures are affected?','Yes. Shared symptoms may point toward a branch drain, main sewer, pressure condition, water source, or equipment problem and should be described together.'],['Do you repair water heaters and sump pumps?','Yes. The residential service scope includes tank and tankless water heaters, sump pumps, backup systems, and connected piping.'],['What areas do you serve?','Residential plumbing service is available across Macomb, Oakland, and Wayne counties. Call with the exact property address to confirm coverage.']]});}

function commercialPage(){return audiencePage({type:'Commercial',hero:'commercial-hero-v4.png',eyebrow:'Commercial plumbing services',title:'Plumbing support built around your property and operation.',lead:'Responsive plumbing service for businesses, facilities, managed properties, and high-use systems across three Southeast Michigan counties.',support:'dsc09538.webp',heading:'The plumbing plan must fit the building and the people using it.',intro:['Commercial plumbing work may involve high-use fixtures, shared restrooms, tenant spaces, kitchens, mechanical rooms, back-of-house systems, buried piping, and operating schedules that limit access or shutdown time. Frost & Kretsch Plumbing supports businesses, facilities, and managed properties with service paths that account for both the plumbing condition and the way the property operates.','When you call, identify the site contact, affected area, business hours, access restrictions, shutoff information, and whether customers, employees, tenants, inventory, or equipment are exposed to water or sewage. Clear coordination helps the team prepare the right specialty and communicate around occupied spaces.'],checklist:['Fixture, restroom, drain, and piping repairs','Sewer camera inspection and underground line work','Water-heater, gas-line, and water-treatment support','Urgent response for active leaks and backups'],slugs:['commercial','emergency','drain-cleaning','sewer-camera','sewer-line','water-heater','leak-pipe','gas-line','water-treatment'],planningHeading:'Prepare the information that keeps a commercial call moving.',planningCopy:['Share the service address, property type, best on-site contact, affected fixtures or systems, and the time the condition began. Explain whether the area can be isolated, whether a shutoff is known, and whether the issue affects customers, tenants, production, food service, sanitation, or normal building access.','For planned work, include equipment details, previous findings, approved access windows, security procedures, and the people who need updates. For an urgent condition, call rather than waiting for an online response and describe any active water release or sewage exposure.'],planningList:['Site address, property use, and on-site contact','Operating hours, access limits, and occupied areas','Affected fixtures, systems, tenants, or departments','Prior repairs, equipment information, or recurring symptoms'],faqItems:[['Do you provide emergency commercial plumbing service?','Yes. Call the main number at any time for active leaks, sewage backups, burst piping, failed essential equipment, and other urgent plumbing conditions.'],['Can you coordinate around occupied properties?','Yes. Share operating hours, access restrictions, tenants, customers, and communication requirements when scheduling.'],['Do you handle commercial drains and sewer lines?','Yes. The commercial scope includes drain cleaning, camera inspection, sewer evaluation, underground repair planning, and excavation when required.'],['What service area do you cover?','Commercial plumbing service is available across Macomb, Oakland, and Wayne counties. Call with the exact property address to confirm coverage.']]});}

const renderers={home:homePage,architecture:architecturePage,services:servicesPage,residential:residentialPage,commercial:commercialPage,'water-heater':waterHeaterPage,'service-areas':serviceAreasPage,chesterfield:chesterfieldPage,about:aboutPage,contact:contactPage};
function initNavigation(){
  const menu=document.querySelector('.menu-btn');
  const links=document.querySelector('.nav-links');
  if(menu&&links)menu.addEventListener('click',()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close':'Menu';});
  const toggles=[...document.querySelectorAll('.submenu-toggle')];
  const closeSubmenus=(except=null)=>toggles.forEach(toggle=>{const item=toggle.closest('.nav-item');if(!item||item===except)return;item.classList.remove('submenu-open');toggle.setAttribute('aria-expanded','false');});
  toggles.forEach(toggle=>toggle.addEventListener('click',event=>{event.stopPropagation();const item=toggle.closest('.nav-item');const open=toggle.getAttribute('aria-expanded')==='true';closeSubmenus(item);item.classList.toggle('submenu-open',!open);toggle.setAttribute('aria-expanded',String(!open));}));
  document.addEventListener('click',()=>closeSubmenus());
  document.addEventListener('keydown',event=>{if(event.key==='Escape')closeSubmenus();});
}
function renderPage(slug){const active=renderers[slug]?slug:'home';const [title,description]=pageMeta[active];document.title=title;const meta=document.querySelector('meta[name="description"]');if(meta)meta.content=description;document.getElementById('app').innerHTML=renderers[active]();document.documentElement.dataset.mockup=active;initNavigation();}

function renderReviewHub(){const items=[['home','Homepage','Homepage','Expanded customer-first homepage using the final approved Macomb system.','v1.3'],['architecture','Full Sitemap & URL Plan','Architecture','Complete proposed core, service, and priority-city URL list.','v1.2'],['services','Services Overview','Service index','Expanded service-selection guidance and final one-page-per-service structure.','v1.3'],['residential','Residential Plumbing Hub','Audience hub','Substantive homeowner guidance, service scope, planning details, and FAQs.','v1.2'],['commercial','Commercial Plumbing Hub','Audience hub','Substantive business/property guidance, coordination details, and FAQs.','v1.2'],['water-heater','Water Heater Service','Service template','Representative substantive core service page with corrected F&K uniform imagery.','v1.2'],['service-areas','Service Area Hub','Local SEO hub','Expanded customer-facing three-county coverage and service guidance.','v1.3'],['chesterfield','Chesterfield Service Page','Location template','Representative priority-city page using the verified headquarters.','v1.2'],['about','About','Standard content','Expanded company story, capabilities, service approach, and FAQs.','v1.3'],['contact','Contact','Contact/form','Phone-first contact page with a non-sending review form.','v1.2']];const grid=document.getElementById('review-grid');grid.innerHTML=items.map(([slug,name,family,description,version])=>`<a class="review-card review-changed" href="${pageUrl(slug)}" target="_blank" rel="noopener"><small>${esc(family)}</small><h2>${esc(name)}</h2><p>${esc(description)}</p><span class="version-badge status-changed">${version} • Ready for review</span><span class="new-tab-note">Opens in a new tab ↗</span></a>`).join('');}
